using CouponBook.Data;
using CouponBook.Data.Entities;
using Microsoft.EntityFrameworkCore;
using CouponBook.Business.Auth;


namespace CouponBook.Business.Redemptions;

public record ScanResult(int CustomerVoucherId, string VoucherTitle, string Terms, int UsesRemaining, string CustomerFirstName);
public record RedemptionResult(int RedemptionId, int UsesRemaining, CustomerVoucherStatus Status, DateTime RedeemedAt);
public interface IRedemptionService { Task<ServiceResult<ScanResult>> ValidateAsync(int userId, string code); Task<ServiceResult<RedemptionResult>> ConfirmAsync(int userId, string code, decimal? billAmount); }
public class RedemptionService : IRedemptionService
{
    private readonly AppDbContext _db; public RedemptionService(AppDbContext db) => _db = db;
    private async Task<(ProviderUser? pu, CustomerVoucher? cv)> Load(int uid, string code, bool track) { var pu = await _db.ProviderUsers.Include(x => x.Provider).Include(x => x.Branch).FirstOrDefaultAsync(x => x.UserId == uid && x.Status == AccountStatus.Active); if (pu == null || pu.Provider.Status != AccountStatus.Active) return (null, null); IQueryable<CustomerVoucher> q = _db.CustomerVouchers.Include(x => x.Voucher).Include(x => x.PurchasedBook).ThenInclude(x => x.Owner); if (!track) q = q.AsNoTracking(); var cv = await q.FirstOrDefaultAsync(x => x.Code == code); return (pu, cv); }
    private static string? Invalid(ProviderUser pu, CustomerVoucher cv) { if (cv.Voucher.ProviderId != pu.ProviderId) return "wrong_provider"; if (pu.Type == ProviderUserType.Branch && (pu.BranchId == null || pu.Branch?.Status != AccountStatus.Active)) return "branch_suspended"; if (cv.PurchasedBook.Status != PurchasedBookStatus.Active || cv.ExpiresAt <= DateTime.UtcNow) return "expired"; if (cv.UsesRemaining <= 0 || cv.Status == CustomerVoucherStatus.Used) return "no_uses_left"; return null; }
    public async Task<ServiceResult<ScanResult>> ValidateAsync(int uid, string code) { var (pu, cv) = await Load(uid, code, false); if (pu == null) return ServiceResult<ScanResult>.Fail("provider_access_denied"); if (cv == null) return ServiceResult<ScanResult>.Fail("invalid_code"); var e = Invalid(pu, cv); if (e != null) return ServiceResult<ScanResult>.Fail(e); var first = (cv.PurchasedBook.Owner?.FullName ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries).FirstOrDefault() ?? ""; return ServiceResult<ScanResult>.Ok(new(cv.Id, cv.TitleSnapshot, cv.TermsSnapshot, cv.UsesRemaining, first)); }
    public async Task<ServiceResult<RedemptionResult>> ConfirmAsync(int uid, string code, decimal? bill) { await using var tx = await _db.Database.BeginTransactionAsync(); var pu = await _db.ProviderUsers.Include(x => x.Provider).Include(x => x.Branch).FirstOrDefaultAsync(x => x.UserId == uid && x.Status == AccountStatus.Active); if (pu == null) return ServiceResult<RedemptionResult>.Fail("provider_access_denied"); var rows = await _db.CustomerVouchers.FromSqlInterpolated($"SELECT * FROM \"CustomerVouchers\" WHERE \"Code\"={code} FOR UPDATE").ToListAsync(); var cv = rows.FirstOrDefault(); if (cv == null) return ServiceResult<RedemptionResult>.Fail("invalid_code"); await _db.Entry(cv).Reference(x => x.Voucher).LoadAsync(); await _db.Entry(cv).Reference(x => x.PurchasedBook).LoadAsync(); var e = Invalid(pu, cv); if (e != null) return ServiceResult<RedemptionResult>.Fail(e); var branchId = pu.BranchId; if (pu.Type == ProviderUserType.Main && branchId == null) return ServiceResult<RedemptionResult>.Fail("branch_required"); cv.UsesRemaining--; cv.Status = cv.UsesRemaining == 0 ? CustomerVoucherStatus.Used : cv.UsesRemaining < cv.UsageLimitSnapshot ? CustomerVoucherStatus.PartlyUsed : CustomerVoucherStatus.Available; var r = new Redemption { CustomerVoucherId = cv.Id, BranchId = branchId!.Value, ProviderUserId = pu.Id, FaceValueSnapshot = cv.FaceValueSnapshot, BillAmount = bill }; _db.Redemptions.Add(r); _db.Notifications.Add(new Notification { UserId = cv.PurchasedBook.OwnerUserId!.Value, Type = "voucher_used", Title = "Voucher used", Body = $"{cv.TitleSnapshot} was redeemed." }); await _db.SaveChangesAsync(); await tx.CommitAsync(); return ServiceResult<RedemptionResult>.Ok(new(r.Id, cv.UsesRemaining, cv.Status, r.RedeemedAt)); }
}
